-- Описания уроков в кабинетах (23.10.2026): «С чего начнём» в «Здоровой спине»
-- проще, у лекции про грыжи – источник цифры, у знакомства в «Жонглировании» –
-- описание. Обновляет только если текст ещё прежний.
UPDATE lessons SET content_md = 'Как пройти курс с пользой и удовольствием. Алексей рассказывает, что важно делать параллельно тренировкам и как выбрать свою интенсивность.'
  WHERE slug = 'vvodnoe' AND content_md = 'Как пройти курс с пользой и удовольствием, чтобы решить свой запрос, с которым вы пришли. Алексей разбирает, что важно сделать параллельно тренировкам и как выбрать свою интенсивность.'
    AND course_id = (SELECT id FROM courses WHERE slug = 'zdorovaya-spina');
UPDATE lessons SET content_md = '«По научным исследованиям, боль в спине, которая вызвана грыжами, это около 5%. Чаще всего спина болит из-за мышечных спазмов, из-за малоподвижного образа жизни». Алексей разбирает, что такое грыжи и протрузии – и чего реально стоит бояться. Источник: клинические рекомендации Американской коллегии врачей и Американского общества боли (Chou R. и соавт., Annals of Internal Medicine, 2007) – симптомная грыжа диска есть примерно у 4% людей, обратившихся к врачу с болью в пояснице.'
  WHERE slug = 'gryzhi-protruzii' AND content_md = '«По научным исследованиям, боль в спине, которая вызвана грыжами, это около 5%. Чаще всего спина болит из-за мышечных спазмов, из-за малоподвижного образа жизни». Алексей разбирает, что такое грыжи и протрузии – и чего реально стоит бояться.'
    AND course_id = (SELECT id FROM courses WHERE slug = 'zdorovaya-spina');
UPDATE lessons SET content_md = 'Как устроен курс и как по нему заниматься: последовательные упражнения, в каждом – понятный критерий перехода. Что подготовить к первому занятию. «Если вы ещё хотя бы чуть-чуть сомневаетесь, что у вас получится, – открывайте первое занятие и занимайтесь».'
  WHERE slug = 'znakomstvo' AND COALESCE(content_md, '') = ''
    AND course_id = (SELECT id FROM courses WHERE slug = 'zhonglirovanie');
